"""An immutable Money value type stored in integer minor units."""
from functools import total_ordering


@total_ordering
class Money:
    __slots__ = ("minor_units", "currency")

    def __init__(self, minor_units, currency):
        # bool is a subclass of int; reject it explicitly.
        if not isinstance(minor_units, int) or isinstance(minor_units, bool):
            raise TypeError("minor_units must be an int")
        if not isinstance(currency, str) or len(currency) != 3:
            raise ValueError("currency must be a 3-letter code")
        object.__setattr__(self, "minor_units", minor_units)
        object.__setattr__(self, "currency", currency.upper())

    def __repr__(self):
        return f"Money({self.minor_units}, {self.currency!r})"

    def __str__(self):
        return f"{self.minor_units / 100:.2f} {self.currency}"

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return (self.minor_units, self.currency) == (other.minor_units, other.currency)

    def __hash__(self):
        return hash((self.minor_units, self.currency))

    def __lt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise TypeError(f"cannot order {self.currency} against {other.currency}")
        return self.minor_units < other.minor_units

    def _check_same_currency(self, other):
        if not isinstance(other, Money):
            raise TypeError("operand must be Money")
        if self.currency != other.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __add__(self, other):
        self._check_same_currency(other)
        return Money(self.minor_units + other.minor_units, self.currency)

    def __sub__(self, other):
        self._check_same_currency(other)
        return Money(self.minor_units - other.minor_units, self.currency)

    def __mul__(self, scalar):
        if isinstance(scalar, bool) or not isinstance(scalar, int):
            raise TypeError("can only multiply Money by an int scalar")
        return Money(self.minor_units * scalar, self.currency)

    __rmul__ = __mul__

    def __bool__(self):
        return self.minor_units != 0

