from money import Money


def test_equality_by_value():
    assert Money(100, "USD") == Money(100, "USD")
    assert Money(100, "USD") != Money(100, "EUR")
    assert Money(100, "USD") != Money(200, "USD")


def test_equal_objects_hash_equal():
    a, b = Money(100, "USD"), Money(100, "USD")
    assert hash(a) == hash(b)
    assert len({a, b}) == 1


def test_usable_as_dict_key():
    prices = {Money(100, "USD"): "cheap", Money(100, "EUR"): "also"}
    assert prices[Money(100, "USD")] == "cheap"


def test_eq_with_other_type_is_false_not_error():
    assert (Money(100, "USD") == "100 USD") is False
